Q: ScrollView positions being restarted on a child component re-render (update) A: <p>I was facing a similar problem. I had a component <code>&lt;CategoryFilterList /&gt;</code> that rendered some pills which are used to filter products by category. I was using <code>&lt;FlashList /&gt;</code> for rendering the product cards and in the <code>ListHeaderComponent</code> prop I was rendering my <code>&lt;CategoryFilterList /&gt;</code>  but I noticed that I was losing the horizontal scroll position in the <code>&lt;CategoryFilterList /&gt;</code> on click of the far right filter.</p>
<p>I solved it by memoizing the value passed to <code>ListHeaderComponent</code> (my CategoryFilterList) so that the scroll position &quot;state&quot; persist through re-renders. Here's an excerpt</p>
<pre><code>
export default function Index() {
  const [searchQuery, setSearchQuery] = useState(&quot;&quot;);
  const [selectedCategory, setSelectedCategory] = useState(&quot;all&quot;);

  const {
    data: products,
    refetch,
    isRefetching,
  } = useQuery({
    queryKey: [&quot;products&quot;],
    queryFn: getProducts,
  });

  const { data: categories } = useQuery({
    queryKey: [&quot;categories&quot;],
    queryFn: getCategories,
  });

  const allCategories = useMemo(() =&gt; {
    return [&quot;all&quot;, ...(categories || [])];
  }, [categories]);

  const filteredProducts = useMemo(() =&gt; {
    return products?.filter((product) =&gt; {
      const matchesTitle = product.title
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

      const matchesDescription = product.description
        .toLowerCase()
        .includes(searchQuery.toLowerCase());

      return matchesTitle || matchesDescription;
    });
  }, [searchQuery, products]);

  const filteredProductsByCategory = useMemo(() =&gt; {
    if (selectedCategory === &quot;all&quot;) {
      return filteredProducts;
    }

    return filteredProducts?.filter((product) =&gt; {
      return product.category === selectedCategory;
    });
  }, [filteredProducts, selectedCategory]);

  const CategoryFilterList = useMemo(
    () =&gt;
      allCategories &amp;&amp; allCategories.length &gt; 0 ? (
        &lt;CategoryList
          categories={allCategories}
          onSelectCategory={setSelectedCategory}
          selectedCategory={selectedCategory ?? &quot;all&quot;}
          style={styles.categoryList}
        /&gt;
      ) : null,
    [allCategories, selectedCategory]
  );

  return (
    &lt;View style={styles.container}&gt;
      &lt;FlashList
        data={filteredProductsByCategory}
        renderItem={({ item: product }) =&gt; (
          &lt;ProductCard style={styles.item} product={product} /&gt;
        )}
        ListHeaderComponent={CategoryFilterList}
      /&gt;
    &lt;/View&gt;
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
  },
  categoryList: {
    marginBottom: 16,
  },
  item: {
    margin: 8,
  },
});
</code></pre>
